{"source": "def investigate(context, acquire):
    receipts = acquire("history")

    def simulate(actions, put_mode, trigger, channel_mode):
        main = {}
        other = {}
        log = 0
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        tx = {}
        tx_log = 0
        tx_mc = 0
        tx_mt = 0
        tx_oc = 0
        tx_ot = 0
        tx_conn = None

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                key = act["key"]
                value = act["value"]
                table = main if conn == "main" else other
                changed = 0
                if put_mode == 0:
                    if key not in table:
                        table[key] = value
                        changed = 1
                elif put_mode == 1:
                    table[key] = value
                    changed = 1
                else:
                    if key in table:
                        if table[key] != value:
                            table[key] = value
                            changed = 1
                    else:
                        table[key] = value
                        changed = 1
                if changed and trigger:
                    log += 1
                if conn == "main":
                    main_changes = changed
                    main_total += changed
                else:
                    other_changes = changed
                    other_total += changed
            elif op == "update":
                key = act["key"]
                value = act["value"]
                table = main if conn == "main" else other
                changed = 0
                if key in table and table[key] != value:
                    table[key] = value
                    changed = 1
                if conn == "main":
                    main_changes = changed
                    main_total += changed
                else:
                    other_changes = changed
                    other_total += changed
            elif op == "delete":
                key = act["key"]
                table = main if conn == "main" else other
                changed = 0
                if key in table:
                    del table[key]
                    changed = 1
                if conn == "main":
                    main_changes = changed
                    main_total += changed
                else:
                    other_changes = changed
                    other_total += changed
            elif op == "begin":
                tx_conn = conn
                if conn == "main":
                    tx = dict(main)
                    tx_log = log
                    tx_mc = main_changes
                    tx_mt = main_total
                else:
                    tx = dict(other)
                    tx_log = log
                    tx_oc = other_changes
                    tx_ot = other_total
            elif op == "commit":
                tx_conn = None
            elif op == "rollback":
                if conn == "main":
                    main.clear()
                    main.update(tx)
                    log = tx_log
                    main_changes = tx_mc
                    main_total = tx_mt
                else:
                    other.clear()
                    other.update(tx)
                    log = tx_log
                    other_changes = tx_oc
                    other_total = tx_ot
                tx_conn = None

        if channel_mode == 0:
            ch = main_changes
        elif channel_mode == 1:
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(main), sum(main.values())

    candidates = []
    for put_mode in range(3):
        for trigger in (False, True):
            for channel_mode in range(3):
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(r["actions"], put_mode, trigger, channel_mode)
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cnt)
        elif goal == "committed_sum":
            vals.add(sm)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
"
, "scope": "Family: put mode (IGNORE/REPLACE/UPSERT), optional AFTER INSERT trigger, channel (changes/total_changes main/total_changes main+other). Simulate all 18 members against receipts, keep consistent ones, answer only if all agree.", "lesson": "Receipts show put twice on same key yields channel 2 and sum 2, so put is REPLACE or UPSERT with trigger or total_changes; rollback restores committed state but channel still counts attempted writes, so channel is total_changes-like, not changes()."}
